    "鏡に映ったもう一人の自分が小さくうなずいた。次の戦闘で最初に使うカードに、鏡写しの力が宿る。": "かがみにうつったもうひとりのじぶんがちいさくうなずいた。つぎのせんとうでさいしょにつかうカードに、かがみうつしのちからがやどる。",
