    "あかり「星冠展開！みんなの願い、ここでつなぐよ！」": "Akari: Star Crown, unfold! I will connect everyone's wishes here!",
    "しずく「月鏡同期。感情ではなく、覚悟で勝ちます」": "Shizuku: Moon Mirror synchronized. I will win with resolve, not emotion.",
    "ひより「命花開花。傷つけるためじゃなく、守るために」": "Hiyori: Life Flower, bloom. Not to hurt, but to protect.",
    "つばさ「神鍛点火！真正面から、ぜんぶ打ち砕く！」": "Tsubasa: Divine forge, ignite! I will smash everything head-on!",
    "れい「影札結界、解放。弱き者へ刃は向けさせない」": "Rei: Shadow-card barrier, release. I will not let blades turn toward the weak.",
    "まどか「時環再起動。失敗した時間ごと、私が進める」": "Madoka: Time ring reboot. I will move forward, failed time and all.",
    "こはる「翠嵐招来。風よ、迷う心を運んで」": "Koharu: Emerald gale, come forth. Wind, carry these wavering hearts.",
    "みらい「夢幻開演。悪夢だって、私の舞台で塗り替える」": "Mirai: Dream stage, begin. Even nightmares can be rewritten on my stage.",
    "セラ「星界接続。二つの世界に、朝を届けます」": "Sera: Astral connection. I will bring morning to both worlds.",
    "蓮「蒼風展開。俺が先に道を開く、ついてこい！」": "Ren: Azure wind, unfold. I will open the way first, so follow me!",
    "颯真「氷律起動。私が責任を持って勝利へ導く」": "Soma: Frost law, activate. I will take responsibility and lead us to victory.",
    "湊「清流共鳴。今度はぼくが、みんなを守ります！」": "Minato: Clear stream resonance. This time, I will protect everyone!",
    "理玖「時詠接続。未来は見るものじゃない、選ぶものだ」": "Riku: Time-reading connection. The future is not something you watch. It is something you choose.",
    "大和「紅蓮装甲。俺の前で、誰にも手ぇ出させねえ！」": "Yamato: Crimson armor. Nobody touches anyone while I stand here!",
    "レオン「幻奏開演。最高の勝利を僕が演出しよう！」": "Leon: Illusion performance, begin. I will direct the perfect victory!",
