    "異なる種類のカードを3枚使うと星座が完成し、敵全体へ星光を放ってブロックを得る。": "Play three different card types to complete the constellation, deal starlight damage to all enemies, and gain Block.",
    "専用カードを3回使うと月鏡が反射し、敵1体へ追加攻撃してブロックを得る。2枚目の専用カードは追加ブロックも得る。": "Play exclusive cards three times to reflect the moon mirror, attack one enemy, and gain Block. The second exclusive card also grants extra Block.",
    "専用カードで種を植え、育て、収穫する。収穫時に回復と全体攻撃が発生する。": "Use exclusive cards to plant, grow, and harvest. Harvesting heals you and attacks all enemies.",
    "専用カードを使うたび炉熱が上がる。炉熱3で手札を強化し、ムキムキを得る。": "Each exclusive card raises forge heat. At heat 3, upgrade your hand and gain Strength.",
    "専用カードで封印札を重ねる。3枚揃うと敵全体を弱体化し、ドクドクを与える。": "Stack seal talismans with exclusive cards. At three seals, weaken all enemies and apply Poison.",
    "専用カードを3回使うと時環が完成し、カード補充・エナジー・ブロックをまとめて得る。順番は自由。": "Play exclusive cards three times to complete the time ring and gain cards, Energy, and Block. Any order works.",
    "専用カードの種類に応じて風・葉・樹の精霊と契約し、3種揃うと全効果を発動する。": "Make contracts with wind, leaf, and tree spirits based on exclusive card types. Collect all three to trigger every effect.",
    "専用カードを演目枠へ置く。3演目が揃うとフィナーレで全体攻撃と弱体化を行う。": "Place exclusive cards into act slots. When all three acts are ready, the finale attacks and weakens all enemies.",
    "専用カードを3回使うと解析が完了し、カード補充・ブロック・ムキムキを得る。順番は自由。": "Play exclusive cards three times to complete analysis and gain cards, Block, and Strength. Any order works.",
    "専用スキルで守護を蓄積し、専用攻撃で守護を消費して追加攻撃する。": "Build Guard with exclusive skills, then spend Guard with exclusive attacks for extra hits.",
    "専用カードを番号順に使うと計画達成。順序が崩れると最初から組み直す。": "Play exclusive cards in numbered order to complete the plan. Wrong order resets progress.",
    "専用カードから治癒水を3滴集め、回復・ブロック・攻撃へ一度に変換する。": "Collect three drops of healing water from exclusive cards, then convert them into healing, Block, and an attack.",
    "専用カードで未来候補を3つ観測する。3候補が揃うと手札補充とエナジーを得る。": "Observe three future options with exclusive cards. When all three are ready, gain cards and Energy.",
    "専用カード使用で闘気を蓄積する。闘気3で敵単体へ大ダメージを与える。": "Exclusive cards build Fighting Spirit. At 3, deal heavy damage to one enemy.",
    "専用カードを音符として並べる。3音揃うと全体へ幻奏フィナーレを放つ。": "Arrange exclusive cards as notes. Three notes unleash an illusion finale on all enemies.",
    "専用カードで星界門を3段階開く。開門完了で星界の加護を召喚する。": "Open the astral gate through three stages with exclusive cards. When it opens, summon astral protection.",
    "専用カードで代償を支払い契約を進める。3段階で強力な封印術を発動する。": "Pay costs with exclusive cards to advance the pact. At stage three, unleash a powerful sealing spell.",
    "星座盤：攻撃・スキル・パワーを1枚ずつ使うと、全体攻撃とブロック。": "Constellation: Use one Attack, Skill, and Power for AoE damage and Block.",
    "月鏡：専用カード3回で、単体追撃・びくびく・ブロック。": "Moon Mirror: Play exclusive cards 3 times for a single-target follow-up, Vulnerable, and Block.",
    "命花壇：種を植えて育てる。収穫で全体攻撃と回復。": "Life Garden: Plant and grow seeds. Harvest for AoE damage and healing.",
    "神鍛炉：専用カードで炉熱を上げ、手札強化・ムキムキ・エナジー。": "Divine Forge: Raise heat with exclusive cards to upgrade your hand, gain Strength, and Energy.",
    "禁札陣：封印札を3枚重ね、全体へへろへろとドクドク。": "Seal Array: Stack 3 seals to apply Weak and Poison to all enemies.",
    "時環記録：専用カード3回で、ドロー・エナジー・ブロック。": "Time Ring: Play exclusive cards 3 times for cards, Energy, and Block.",
    "精霊樹：3種の精霊契約で、全体攻撃・ブロック・ドロー。": "Spirit Tree: Complete 3 spirit contracts for AoE damage, Block, and cards.",
    "夢幻舞台：3演目を揃え、全体攻撃・へろへろ・エナジー。": "Dream Stage: Set 3 acts for AoE damage, Weak, and Energy.",
    "星界記録：専用カード3回で、ドロー・ブロック・ムキムキ。": "Astral Log: Play exclusive cards 3 times for cards, Block, and Strength.",
    "蒼風護陣：守護をためて攻撃で消費。単体追撃とブロック。": "Blue Wind Guard: Build Guard, then spend it on attacks for a follow-up hit and Block.",
    "氷律計画：専用カードを番号順に使うと、全体攻撃と弱体化。": "Ice Plan: Play exclusive cards in order for AoE damage and debuffs.",
    "清流調合：治癒水を3滴集め、回復・ブロック・攻撃に変換。": "Clear Stream Mix: Collect 3 healing drops, then convert them into healing, Block, and damage.",
    "分岐盤：未来候補を3つ観測し、ドロー・エナジー・ブロック。": "Branch Board: Observe 3 futures for cards, Energy, and Block.",
    "紅蓮決闘：闘気を3ためて、単体大ダメージとムキムキ。": "Crimson Duel: Build 3 Fighting Spirit for heavy single-target damage and Strength.",
    "幻奏譜：音符を3つ揃え、全体攻撃とドロー。": "Illusion Score: Line up 3 notes for AoE damage and cards.",
    "星界門：星界門を3段階開き、回復・ブロック・ムキムキ。": "Astral Gate: Open 3 gate stages for healing, Block, and Strength.",
    "常夜契約：代償で契約を進め、全体へドクドクとへろへろ。": "Eternal Night Pact: Pay costs to advance the pact, then apply Poison and Weak to all enemies.",
    "攻撃・スキル・パワーを各1種類使う。順番は自由で、同じ種類を重ねても進行しない。専用カード以外も対象。": "Play one Attack, one Skill, and one Power in any order. Repeating a type does not advance progress. Non-exclusive cards count too.",
    "専用カードを左から順に1枚目→2枚目→3枚目と使う。途中で違う順番の専用カードを使うと進行がリセットされる。": "Play exclusive cards from left to right: first, second, then third. Playing a different order resets progress.",
    "この主人公の専用カードを合計3回使う。同じカードを複数回使っても進行する。3回目のカード効果後に完成効果が発動する。": "Play this protagonist's exclusive cards three total times. Repeating the same card still advances progress. The completion effect triggers after the third card resolves.",
    "完成時に主人公ごとの追加効果が発動し、その後専用UIの進行は空に戻る。": "On completion, the protagonist's bonus effect triggers, then this UI progress resets.",

