    "願いの夜明け": "Dawn of Wishes",
    "あなたは真・校長の支配を打ち破り、\nこの学園に自分たちの明日を取り戻しました。\n反逆の卒業生として、その名は校内伝説に刻まれるでしょう。": "You broke the True Principal's control and reclaimed your own tomorrow for this academy.\nAs rebellious graduates, your names will be carved into school legend.",
    "あなたは大魔女校長が作り出した「願いの檻」を打ち破り、\n学園に自由な未来と朝の光を取り戻しました。\n学び、迷い、誰かを大切にした日々は、これからもあなたの魔法を強くしていくでしょう。": "You shattered the Cage of Wishes created by the Great Witch Principal and restored a free future and morning light to the academy.\nThe days you spent learning, wavering, and caring for someone will keep strengthening your magic.",
