Object.assign(ENGLISH_DICTIONARY, {
    // Full event descriptions: high-school and magic themes
    "【攻撃タイプ】高い体力と正面突破の攻撃で戦う、扱いやすい高校編の主人公。": "[Attack Type] An easy-to-use high school protagonist who fights with high HP and direct attacks.",
    "【捕獲タイプ】生物部で培った観察眼を活かし、倒した敵をカード化して戦う。": "[Capture Type] Uses observation skills from biology club to turn defeated enemies into cards.",
    "【テクニカル】毒による継続ダメージが得意。反逆の高校生が最初からパートナーとして参戦する。": "[Technical] Excels at damage over time with Poison. The Rebellious High Schooler joins as a partner from the start.",
    "【実験タイプ】3枚のカードを合成し、複数効果を持つキメラカードを作成できる。": "[Experiment Type] Can synthesize three cards into a chimera card with multiple effects.",
    "【スピード】ドローとディスカードを軸に動き、ドッジボールで先制攻撃を狙える。": "[Speed] Plays around drawing and discarding, then aims for first strikes with dodgeball attacks.",
    "【スピード】ドローとディスカードを軸に動き、速攻レイアップで戦闘スキップを狙える。": "[Speed] Plays around drawing and discarding, then aims to skip battles with fast-break layups.",
    "【デバフ・反射】敵を弱体化し、応答で攻撃を跳ね返す放送部の戦術家。": "[Debuff / Reflect] A broadcasting club tactician who weakens enemies and reflects attacks with responses.",
    "【戦略・保留】手札を残す保留と物語カードで、戦局をじっくり組み立てる。": "[Strategy / Retain] Uses retained hands and story cards to carefully build the battle state.",
    "【パワー】開始時に解放済みカードから初期デッキを組み、重い一撃で押し切る。": "[Power] Builds a starting deck from unlocked cards and wins with heavy blows.",
    "【育成タイプ】菜園で種を育て、強力な植物カードへ成長させて戦う大器晩成型。": "[Growth Type] A late bloomer who raises seeds in the garden into powerful plant cards.",
    "誰もいない自習室に、まだ消えていないスタンドライトが一つだけ残っている。": "In the empty study room, a single desk lamp is still glowing.",
    "夕焼けの屋上に風だけが通る。少し立ち止まるにはちょうどいい。": "Only the wind crosses the sunset rooftop. It is just right for a short pause.",
    "赤い丸が並ぶ答案が返ってきた。次の一手を考える時間だ。": "A test paper covered in red circles has been returned. It is time to think about your next move.",
    "教室は装飾と段ボールでいっぱいだ。手伝えば何か得るものがありそうだ。": "The classroom is packed with decorations and cardboard. Helping out may earn you something.",
    "放課後の廊下に、色とりどりの部活ポスターが並んでいる。": "After school, colorful club posters line the hallway.",
    "フラスコから光が噴き上がった。危険だが、珍しい成果も期待できる。": "Light bursts from the flask. It is dangerous, but a rare result may be possible.",
    "帰り道のコンビニで少しだけ息をつく。補給するか、先を急ぐか。": "You catch your breath at a convenience store on the way home. Restock, or hurry onward?",
    "生徒会室の机に、未整理の資料が高く積まれている。": "Unsorted documents are piled high on the student council room desk.",
    "雨に煙る校門で、帰るべきか、もう少しだけ残るべきか迷う。": "At the rain-blurred school gate, you hesitate between going home and staying a little longer.",
    "人気のない教室に、夕方の光だけが静かに残っている。": "In the deserted classroom, only the evening light quietly remains.",
    "人気のない音楽室で、譜面台だけが夕日を受けている。": "In the empty music room, only the music stands catch the sunset.",
    "静かな体育館に、水筒とタオルだけが残されている。": "In the quiet gym, only a water bottle and towel have been left behind.",
    "閉館後の図書室に、読みかけの本と灯りが一つ残っている。": "After closing time in the library, an unfinished book and a single light remain.",
    "濡れた自転車が並ぶ駐輪場に、雨上がりの光が差している。": "After-rain light falls across the bicycle lot lined with wet bikes.",
    "白いベッドとカーテンの向こうで、時間だけがゆっくり進んでいる。": "Beyond the white beds and curtains, only time moves slowly.",
    "描きかけのキャンバスが、誰かの途中の決意を映している。": "An unfinished canvas reflects someone's half-formed resolve.",
    "開け放たれた昇降口を、放課後の風が静かに抜けていく。": "The after-school wind quietly passes through the open entryway.",
    "終電前のホームに、人の気配だけが薄く残っている。": "On the platform before the last train, only faint traces of people remain.",
    "桜が舞う校門に、新しい制服のざわめきが満ちている。": "Cherry blossoms dance at the school gate, filled with the rustle of new uniforms.",
    "先輩たちの声が飛び交い、部活のチラシが春風に揺れる。": "Upperclassmen call out as club flyers sway in the spring breeze.",
    "教室の真ん中で、次の景色を決める小さなくじが回っている。": "In the middle of the classroom, a small lottery decides the next view.",
    "弁当を広げた友人たちの笑い声が、青空へ抜けていく。": "The laughter of friends with open lunch boxes drifts into the blue sky.",
    "雨粒の向こうで、一本の傘を分け合う二人が立ち止まる。": "Beyond the raindrops, two people pause under a shared umbrella.",
    "教師が差し出したノートに、赤字の助言が丁寧に並んでいる。": "In the notebook the teacher offers, red-ink advice is carefully written out.",
    "長机を囲む声の中に、学校を動かす空気が少しだけ見える。": "Around the long table, the voices reveal a glimpse of how the school is run.",
    "花びらを掃く手元に、春の終わりが静かに積もっていく。": "As petals are swept away, the end of spring quietly gathers at your hands.",
    "開いた靴箱の奥に、差出人のない封筒が一通だけ残されている。": "In the back of the open shoe locker, one unsigned envelope remains.",
    "乾いた土を蹴る足音と声援が、真夏の校庭を震わせる。": "Footsteps kicking dry dirt and cheering voices shake the midsummer schoolyard.",
    "部室では氷とシロップが並び、祭り前の熱気が立ちのぼる。": "In the clubroom, ice and syrup are lined up as pre-festival excitement rises.",
    "図書室の机に参考書が積まれ、眠気より焦りが勝っている。": "Reference books are stacked on the library desk, and urgency is beating sleepiness.",
    "窓の外の蝉と扇風機だけが、午後の時間を進めている。": "Only the cicadas outside and the fan keep the afternoon moving.",
    "プールサイドに水滴が光り、練習後の息が少しずつ整う。": "Water drops shine by the poolside as breathing slowly settles after practice.",
    "夜空に開く光を、言葉少なに見上げる影が並ぶ。": "Silent figures line up, looking up at lights blooming in the night sky.",
    "音楽室に重なる音が、まだ未完成の曲を少しずつ形にする。": "Layered sounds in the music room slowly shape an unfinished piece.",
    "湿った夕方、買ったばかりの飲み物が手のひらを冷やす。": "On a humid evening, a freshly bought drink cools your palm.",
    "屋根を打つ雨音の下で、帰れない生徒たちが空を見上げる。": "Under rain striking the roof, students who cannot go home look up at the sky.",
    "段ボールと絵の具の匂いの中、教室が別の世界へ変わっていく。": "Amid the smell of cardboard and paint, the classroom transforms into another world.",
    "赤い葉を追う鉛筆の線が、静かな秋を紙に留めていく。": "Pencil lines following red leaves capture a quiet autumn on paper.",
    "教師の問いかけの前で、未来が少しだけ具体的な形を持つ。": "Before the teacher's question, the future takes on a slightly clearer shape.",
    "大きな鞄と期待を抱えた列が、発車ベルを待っている。": "A line carrying big bags and expectations waits for the departure bell.",
    "長い影の中で、最後の一球まで声が途切れない。": "In the long shadows, voices do not stop until the final pitch.",
    "甘い香りが広がり、失敗も笑いに変わる午後になる。": "A sweet smell spreads, turning even mistakes into laughter that afternoon.",
    "廊下の片隅で、質問の一つひとつが相手の輪郭を映していく。": "In a corner of the hallway, each question brings the other person into clearer focus.",
    "体育館裏の道を、友人との会話がゆっくり進んでいく。": "Along the path behind the gym, conversation with a friend moves slowly onward.",
    "張り出された紙の前に、人の波とため息が重なっている。": "In front of the posted results, a wave of people and sighs overlap.",
    "白く染まった通学路で、足音だけがいつもより柔らかい。": "On the white-covered school route, even footsteps sound softer than usual.",
    "登校直後の教室に、人が少しずつ温まりに集まってくる。": "Just after arrival, students slowly gather in the classroom to warm up.",
    "飾り付けられた廊下で、手渡す品物に小さな善意が混じる。": "In the decorated hallway, small kindness mixes into the items being handed over.",
    "冬休み明けの仲間たちが、境内でそれぞれの願いを結ぶ。": "Friends just back from winter break tie up their separate wishes at the shrine.",
    "机の上の数字を前に、焦りと覚悟が同じ椅子に座っている。": "Facing the numbers on the desk, anxiety and resolve sit in the same chair.",
    "夕方の昇降口で、小さな箱が思い切りの証になる。": "At the evening entryway, a small box becomes proof of courage.",
    "花束と拍手の間を、三年間の時間が静かに通り過ぎていく。": "Between bouquets and applause, three years pass quietly by.",
    "誰もいない教室に、夕日だけが最後まで残っている。": "In the empty classroom, only the sunset remains until the end.",
    "参考書とドリンクバーの明かりの中で、友人たちがまだ粘っている。": "Under reference books and the drink bar lights, friends are still holding on.",
    "黒板に浮かぶ星図が、今日の選択を静かに照らしている。": "The star chart floating on the blackboard quietly lights today's choice.",
    "月の光を浴びた噴水の前で、誰かがひとり考え込んでいる。": "In front of the moonlit fountain, someone is deep in thought alone.",
    "訓練場に咲いた魔法の花が、正しい道と危険な道を隠している。": "Magical flowers blooming in the training field hide both the right path and the dangerous one.",
    "実技室の結界内で、炎の軌跡が勇気と焦りを映し出す。": "Inside the practical room's barrier, trails of flame reflect courage and impatience.",
    "禁書棚の奥で、見覚えのない栞が小さく光っている。": "Deep in the forbidden bookshelf, an unfamiliar bookmark glows faintly.",
    "止まった時計の針が、やり直したい一問を指している。": "The hands of a stopped clock point to one question you want to redo.",
    "屋上を抜ける風に、言えなかった言葉が少しだけ軽くなる。": "In the wind crossing the rooftop, words left unsaid grow a little lighter.",
    "白いカーテンの向こうで、誰かの悪夢が淡い光になって揺れる。": "Beyond the white curtain, someone's nightmare sways as pale light.",
    "ステンドグラスの下で、使命と願いのどちらを選ぶか問われる。": "Beneath the stained glass, you are asked whether to choose duty or desire.",
    "廊下の床に現れた魔法陣が、次の出会いへ導いている。": "A magic circle on the hallway floor guides you toward the next encounter.",
    "端末に届いた短いメッセージが、学園の裏側の異変を告げる。": "A short message on your device warns of trouble behind the academy's surface.",
    "棚に並ぶ不思議な小物の中に、今日だけ役立つ品が混じっている。": "Among the strange trinkets on the shelf is something useful only today.",
    "夜の共有スペースで、仲間たちが明日の作戦を小声で話し合う。": "In the shared space at night, friends quietly discuss tomorrow's plan.",
    "休日の水槽前で、戦いから離れた一瞬の本音がこぼれる。": "Before a holiday aquarium tank, a rare honest feeling slips out away from battle.",
    "屋台の明かりに紛れて、薄い結界のほころびが見えている。": "Amid the stall lights, you can see a thin barrier beginning to fray.",
    "舞台袖の暗がりで、誰かの魔法と恋心が同時に揺れている。": "In the darkness offstage, someone's magic and romantic feelings waver together.",
    "イルミネーションの中に、異世界からの淡い信号が混じっている。": "Among the illuminations, a faint signal from another world is mixed in.",
    "小さな包みに込めた気持ちが、魔力より強く胸を鳴らす。": "The feeling tucked into a small package makes your heart beat louder than magic.",
    "最後の夜、九人の願いが星空の下でひとつの答えに近づく。": "On the final night, nine wishes move closer to one answer beneath the stars.",
    "誰もいない訓練場で、変身後の自分と向き合う時間が始まる。": "In the empty training field, your time facing your transformed self begins.",
});

