    "色相性: 橙 > 青 > 白。上位の色は下位のスロットにも使えます。": "Color matchup: Orange > Blue > White. Higher colors can also fill lower slots.",
    "スロットを全て埋めると起動ボーナスが発生します。": "Fill every slot to trigger an activation bonus.",
    "砲台: 同じ行に攻撃出力を出す基本攻撃パーツです。": "Cannon: a basic attack part that outputs attack power on the same row.",
    "ミサイル: 砲台より高出力になりやすい攻撃パーツです。": "Missile: an attack part that more easily reaches higher output than cannons.",
    "盾: 行のぶつかり合いで受けるダメージを抑える防御パーツです。": "Shield: a defense part that reduces damage in row clashes.",
    "エンジン: 燃料・移動・特殊効果で戦いやすさを支える補助パーツです。": "Engine: a support part that helps with fuel, movement, and special effects.",
    "増幅器: 隣接パーツの出力を上げる支援パーツです。": "Amplifier: a support part that boosts adjacent parts' output.",
    "クラッシュバトル: 自機と敵機の同じ行(Row)同士がぶつかり合います。": "Crash Battle: your plane and the enemy plane clash row by row.",
    "出力の高い方が、差分をダメージとして相手に与えます。": "The higher output side deals the difference as damage.",
    "FIREボタン: 攻撃を実行し、ターンを進めます。": "FIRE button: execute attacks and advance the turn.",
    "移動: 上下に移動して敵の攻撃を避けたり、有利な位置を取りましょう（燃料消費）。": "Move: move up or down to dodge enemy attacks or take a better position. This consumes fuel.",
    "ステージクリア後は休暇パートに入ります。": "After clearing a stage, you enter the vacation phase.",
    "日数を消費して修理や強化を行います。": "Spend days to repair and upgrade.",
    "ショップ: スターコインを使って強力なパーツを購入できます。": "Shop: spend Star Coins to buy powerful parts.",
    "格納庫: パーツの配置換えや保管ができます。": "Hangar: rearrange and store parts.",
    "数値: スロットに入れた時の出力パワーになります。": "Value: output power when placed into a slot.",
