const translateHiraganaDynamicUi = (text: string): string | null => {
    const patterns: Array<[RegExp, (...matches: string[]) => string]> = [
        [/^通常攻撃: (\d+)ダメージ$/, (_, damage) => `つうじょうこうげき: ${damage}ダメージ`],
        [/^防御: ブロック(\d+)$/, (_, block) => `ぼうぎょ: ブロック${block}`],
        [/^攻撃しつつ防御: (\d+)ダメージ \/ ブロック(\d+)$/, (_, damage, block) => `こうげきしつつぼうぎょ: ${damage}ダメージ / ブロック${block}`],
        [/^特殊攻撃: (\d+)ダメージ \+ 粘液\(状態異常カード\)(?: (\d+))?$/, (_, damage, amount = '') => `とくしゅこうげき: ${damage}ダメージ + ねんえき(じょうたいいじょうカード)${amount ? ` ${amount}` : ''}`],
        [/^特殊攻撃: 防御貫通で(\d+)ダメージ$/, (_, damage) => `とくしゅこうげき: ぼうぎょをむしして${damage}ダメージ`],
        [/^強化行動: (.+)$/, (_, detail) => `きょうかこうどう: ${detail}`],
        [/^妨害行動: (.+)$/, (_, detail) => `ぼうがいこうどう: ${detail}`],
        [/^敵HP x(\d+\.\d+)$/, (_, multiplier) => `てきHP x${multiplier}`],
        [/^休憩時理科室 (\d+)%$/, (_, chance) => `きゅうけいじ りかしつ ${chance}%`],
        [/^削除費 \+(\d+)G$/, (_, cost) => `さくじょひ +${cost}G`],
        [/^(.+)をカード帳から持ってきた。$/, (_, name) => `${name}をカードちょうからもってきた。`],
        [/^天気予報：(\d+)枚を山札に戻し、(\d+)枚を捨て札に送った$/, (_, keep, discard) => `てんきよほう：${keep}まいをやまふだにもどし、${discard}まいをすてふだにおくった`],
        [/^銀河鉄道の夜：(.+)を手札に加え、残り(\d+)枚を捨て札に送った$/, (_, name, discard) => `ぎんがてつどうのよる：${name}をてふだにくわえ、のこり${discard}まいをすてふだにおくった`],
        [/^今ターン失ったHPを力に変えた！ \((\d+)ダメージ\)$/, (_, damage) => `いまのターンでうしなったHPをちからにかえた！ (${damage}ダメージ)`],
        [/^魅惑のカカオ：手札を(\d+)枚入れ替えた$/, (_, count) => `みわくのカカオ：てふだを${count}まいいれかえた`],
        [/^鉄棒の逆上がり：捨て札から「(.+)」を回収した！$/, (_, name) => `てつぼうのさかあがり：すてふだから「${name}」をかいしゅうした！`],
        [/^電脳世界へのダイブ：「(.+)」を0コスト化$/, (_, name) => `でんのうせかいへのダイブ：「${name}」を0コストにした`],
        [/^次元跳躍：悪いカードを(\d+)枚消滅させ、ムキムキになった！$/, (_, count) => `じげんちょうやく：わるいカードを${count}まいけし、ムキムキになった！`],
        [/^お姫様の呼び声：山札から「(.+)」を引き寄せた$/, (_, name) => `おひめさまのよびごえ：やまふだから「${name}」をひきよせた`],
        [/^(.+)はかかしに見惚れている\.\.\.$/, (_, name) => `${name}はかかしにみとれている...`],
    ];
    for (const [pattern, build] of patterns) {
        const match = text.match(pattern);
        if (match) return build(...match);
    }
    const dynamicRuleSpecificity = (rule: { pattern: RegExp }) => rule.pattern.source.replace(/\(\.\*\?\)/g, '').length;
    const dynamicRules = [...HIRAGANA_DYNAMIC_UI_RULES].sort((a, b) => dynamicRuleSpecificity(b) - dynamicRuleSpecificity(a));
    for (const rule of dynamicRules) {
        if (rule.pattern.test(text)) return text.replace(rule.pattern, rule.replacement);
    }
    return null;
};

export const trans = (text: string, mode: LanguageMode): string => {
    if (!text) return "";
    if (mode === 'JAPANESE') return text;
    if (mode === 'ENGLISH') {
        if (ENGLISH_DISPLAY_COPY_EXACT[text]) return ENGLISH_DISPLAY_COPY_EXACT[text];
        if (ENGLISH_DEBUG_UI_EXACT[text]) return ENGLISH_DEBUG_UI_EXACT[text];
        if (ENGLISH_RUNTIME_EXACT[text]) return ENGLISH_RUNTIME_EXACT[text];
        if (ENGLISH_ENDING_EXACT[text]) return ENGLISH_ENDING_EXACT[text];
        const schoolEventExact = buildEnglishSchoolEventFallback(text);
        if (schoolEventExact) return schoolEventExact;

        const enemyCatalogDescription = translateEnglishEnemyCatalogDescription(text);
        if (enemyCatalogDescription) return enemyCatalogDescription;

        if (ENGLISH_DICTIONARY[text]) return ENGLISH_DICTIONARY[text];
        if (ENGLISH_CARD_NAME_DICTIONARY[text]) return ENGLISH_CARD_NAME_DICTIONARY[text];
        if (ENGLISH_GENERATED_CARD_NAME_DICTIONARY[text]) return ENGLISH_GENERATED_CARD_NAME_DICTIONARY[text];
        if (ENGLISH_ITEM_NAME_DICTIONARY[text]) return ENGLISH_ITEM_NAME_DICTIONARY[text];
        if (ENGLISH_ENEMY_NAME_DICTIONARY[text]) return ENGLISH_ENEMY_NAME_DICTIONARY[text];

        const newSeed = text.match(/^新しい種「(.+)」を手に入れた！$/);
        if (newSeed) return `Obtained a new Seed: "${newSeed[1]}"!`;
        const cyberspaceDive = text.match(/^電脳世界へのダイブ：「(.+)」を0コスト化$/);
        if (cyberspaceDive) return `Dive into Cyberspace: "${cyberspaceDive[1]}" now costs 0.`;
        const princessCall = text.match(/^お姫様の呼び声：山札から「(.+)」を引き寄せた$/);
        if (princessCall) return `Princess Call: Drew "${princessCall[1]}" from the draw pile.`;
        const albumStarter = text.match(/^(.+)をカード帳から持ってきた。$/);
        if (albumStarter) return `Brought ${trans(albumStarter[1], mode)} from the Card Album.`;
        const missingExperimentCards = text.match(/^実験材料（カード）が(\d+)枚足りない\.\.\.$/);
        if (missingExperimentCards) return `You need ${missingExperimentCards[1]} more experiment material card(s)...`;

        const eventTitleTranslation = translateEnglishEventTitle(text);
        if (eventTitleTranslation) return eventTitleTranslation;

        const eventFullTranslation = buildEnglishEventFullTranslation(text);
        if (eventFullTranslation) return eventFullTranslation;

        let result = text;
        Object.keys({ ...ENGLISH_DICTIONARY, ...ENGLISH_ENEMY_NAME_DICTIONARY, ...ENGLISH_ITEM_NAME_DICTIONARY, ...ENGLISH_GENERATED_CARD_NAME_DICTIONARY, ...ENGLISH_CARD_NAME_DICTIONARY })
            .sort((a, b) => b.length - a.length)
            .forEach(key => {
                if (result.includes(key)) {
                    const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    const regex = new RegExp(escapedKey, 'g');
                    result = result.replace(regex, ENGLISH_CARD_NAME_DICTIONARY[key] || ENGLISH_GENERATED_CARD_NAME_DICTIONARY[key] || ENGLISH_ITEM_NAME_DICTIONARY[key] || ENGLISH_ENEMY_NAME_DICTIONARY[key] || ENGLISH_DICTIONARY[key]);
                }
            });

        return sanitizeEnglishText(result);
    }

    // 辞書に完全一致がある場合はそれを返す
    if (HIRAGANA_DISPLAY_COPY_EXACT[text]) return HIRAGANA_DISPLAY_COPY_EXACT[text];
    if (HIRAGANA_DEBUG_UI_EXACT[text]) return HIRAGANA_DEBUG_UI_EXACT[text];
    if (HIRAGANA_ENDING_EXACT[text]) return HIRAGANA_ENDING_EXACT[text];
    if (HIRAGANA_RUNTIME_EXACT[text]) return HIRAGANA_RUNTIME_EXACT[text];
    if (HIRAGANA_UI_EXACT[text]) return HIRAGANA_UI_EXACT[text];
    if (HIRAGANA_COMPENDIUM_EXACT[text]) return HIRAGANA_COMPENDIUM_EXACT[text];
    if (DICTIONARY[text]) return DICTIONARY[text];

    const dynamicUiTranslation = translateHiraganaDynamicUi(text);
    if (dynamicUiTranslation) return dynamicUiTranslation;

    // 部分置換ロジック
    let result = text;
    Object.keys(HIRAGANA_RUNTIME_PARTIAL)
        .sort((a, b) => b.length - a.length)
        .forEach(key => {
            result = result.replaceAll(key, HIRAGANA_RUNTIME_PARTIAL[key]);
        });
    KEYWORDS.forEach(key => {
        if (result.includes(key)) {
            // キーワードに含まれる正規表現の特殊文字をエスケープする
            const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const regex = new RegExp(escapedKey, 'g');
            result = result.replace(regex, DICTIONARY[key]);
        }
    });

    // 共通の記号や単位の微調整
    result = result.replace(/ダメージ/g, "ダメージ");
    result = result.replace(/ブロック/g, "ブロック");
    result = result.replace(/HP/g, "HP");
    result = result.replace(/E(\d+)/g, "エナジー$1");

    // 小数点を保護してから句読点を統一する。
    result = result.replace(/(\d)\.(\d)/g, "$1__DECIMAL_DOT__$2");
    result = result.replace(/\.\.\./g, "__ELLIPSIS__");
    result = result.replace(/\./g, "。");
    result = result.replace(/__DECIMAL_DOT__/g, ".");
    result = result.replace(/__ELLIPSIS__/g, "……");
    result = result.replace(/,/g, "、");

    return result;
};

export const transEventText = (text: string, mode: LanguageMode): string => {
    if (mode === 'ENGLISH' && ENGLISH_DISPLAY_COPY_EXACT[text]) return ENGLISH_DISPLAY_COPY_EXACT[text];
    if (mode === 'HIRAGANA' && HIRAGANA_DISPLAY_COPY_EXACT[text]) return HIRAGANA_DISPLAY_COPY_EXACT[text];
    if (mode === 'ENGLISH' && ENGLISH_DEBUG_UI_EXACT[text]) return ENGLISH_DEBUG_UI_EXACT[text];
    if (mode === 'HIRAGANA' && HIRAGANA_DEBUG_UI_EXACT[text]) return HIRAGANA_DEBUG_UI_EXACT[text];
    if (!text) return "";
    if (mode === 'HIRAGANA') return buildHiraganaEventFallback(text);
    if (mode !== 'ENGLISH') return trans(text, mode);
    if (ENGLISH_RUNTIME_EXACT[text]) return ENGLISH_RUNTIME_EXACT[text];
    if (ENGLISH_ENDING_EXACT[text]) return ENGLISH_ENDING_EXACT[text];

    const earlyExact = buildEnglishSchoolEventFallback(text);
    if (earlyExact) return earlyExact;
    const earlyFull = buildEnglishEventFullTranslation(text);
    if (earlyFull) return earlyFull;

    const base = trans(text, mode);
    if (/HP|G|カード|レリック|呪い|ポーション|最大HP|恒久|強化|獲得|回復|状態異常|習得/.test(text)) {
        const effectFirst = translateEventSentence(text);
        if (effectFirst && !JAPANESE_TEXT_PATTERN.test(effectFirst) && !/[、。！？]/.test(effectFirst) && !/^You handled the (event|situation)/.test(effectFirst)) {
            return effectFirst;
        }
    }
    const weakBase =
        JAPANESE_TEXT_PATTERN.test(base) ||
        /Choose Option|Event Details|School Foe|Discovery\./.test(base) ||
        /Choose a Thoughtful Response|A magical academy event unfolds/.test(base) ||
        /^Upgrade card\(s\)\.?$/.test(base.trim()) ||
        /[、。！？]/.test(base) ||
        /^[\s,.;:!、。！？ー…-]+/.test(base) ||
        base.trim().split(/\s+/).length < 2;
    if (!weakBase) return base;

    const exact = buildEnglishSchoolEventFallback(text);
    if (exact) return exact;
    const full = buildEnglishEventFullTranslation(text);
    if (full) return full;
    if (/HP|G|カード|レリック|呪い|ポーション|最大HP|恒久|強化|獲得|回復|状態異常|習得/.test(text)) {
        const effectOnly = translateEventSentence(text);
        if (effectOnly && !JAPANESE_TEXT_PATTERN.test(effectOnly) && !/[、。！？]/.test(effectOnly) && !/^You handled the (event|situation)/.test(effectOnly)) {
            return effectOnly;
        }
    }
    if (/^[^。\n！？]+$/.test(text)) {
        const sentence = translateEventSentence(text);
        if (
            sentence &&
            !JAPANESE_TEXT_PATTERN.test(sentence) &&
            !/[、。！？]/.test(sentence) &&
            !/^You handled the (event|situation)/.test(sentence) &&
            !/Choose Option|Choose a fitting event action|Event Details|School Foe/.test(sentence)
        ) {
            return sentence;
        }
        return "Choose a fitting event action";
    }
    if (/[。！？…]|\.{3}/.test(text)) {
        const sentence = translateEventSentence(text);
        if (sentence && !JAPANESE_TEXT_PATTERN.test(sentence) && !/[、。！？]/.test(sentence)) return sentence;
        return "You handled the situation carefully and turned the experience into progress.";
    }
    return base;
};

export const transProblemSubjectName = (text: string, mode: LanguageMode): string => {
    if (!text) return "";
    if (mode === 'JAPANESE') return text;
    if (mode === 'ENGLISH') {
        const gradeTerm = text.match(/^([算数国英生理社])\s*(小|中)(\d)\s*(\d)学期$/);
        if (gradeTerm) {
            const subjectMap: Record<string, string> = {
                "算": "Math",
                "数": "Math",
                "国": "Japanese",
                "英": "English",
                "生": "Life",
                "理": "Science",
                "社": "Social Studies",
            };
            const school = gradeTerm[2] === "小" ? "G" : "JH ";
            return `${subjectMap[gradeTerm[1]] || "Subject"} ${school}${gradeTerm[3]} Term ${gradeTerm[4]}`;
        }
        const gradeOnly = text.match(/^([国英])\s*(小|中)(\d)$/);
        if (gradeOnly) {
            const subjectMap: Record<string, string> = {
                "国": "Japanese",
                "英": "English",
            };
            const school = gradeOnly[2] === "小" ? "G" : "JH ";
            return `${subjectMap[gradeOnly[1]] || "Subject"} ${school}${gradeOnly[3]}`;
        }
        const kanjiGrade = text.match(/^(小学|中学)(\d)年$/);
        if (kanjiGrade) return `${kanjiGrade[1] === "小学" ? "Grade" : "JH"} ${kanjiGrade[2]}`;
        return PROBLEM_SUBJECT_ENGLISH_MAP[text] || trans(text, mode);
    }
    return PROBLEM_SUBJECT_HIRAGANA_MAP[text] || trans(text, mode);
};
